<div class="proma-customer-360__overview-grid"><section class="card"><div class="card-header"><div><h2>تماس‌های ثبت‌شده</h2><p class="text-muted">آخرین ۵۰ تماس</p></div></div><div class="proma-customer-360__list"><?php foreach (($calls ?? []) as $call): ?><article class="proma-customer-360__row"><span><strong><?= e($call['call_result'] ?: 'تماس اپراتور') ?> · <?= e($call['contract_number'] ?? '') ?></strong><small><?= e($call['operator_name'] ?? 'اپراتور نامشخص') ?> · <?= e(jdatetime($call['created_at'] ?? '')) ?></small><?php if (!empty($call['notes'])): ?><small><?= e($call['notes']) ?></small><?php endif; ?></span><?php if (!empty($call['next_followup_date'])): ?><b>پیگیری <?= e(jdate($call['next_followup_date'])) ?></b><?php endif; ?></article><?php endforeach; ?><?php if (empty($calls)): ?><div class="proma-empty-state"><p>تماسی ثبت نشده است.</p></div><?php endif; ?></div></section>
<section class="card"><div class="card-header"><div><h2>پیگیری‌های زمان‌بندی‌شده</h2><p class="text-muted">شامل وظایف خودکار وصول و بررسی حقوقی</p></div></div><div class="proma-customer-360__list"><?php foreach (($followups ?? []) as $event): ?><article class="proma-customer-360__row"><span><strong><?= e($event['title']) ?></strong><small><?= e($event['assigned_name'] ?? 'بدون مسئول') ?> · <?= e(jdate($event['event_date'] ?? '')) ?></small><small><?= e($event['description'] ?? '') ?></small></span><em class="badge <?= e($event['color'] === 'danger' ? 'badge-light-danger' : 'badge-light-warning') ?>"><?= e(Event::eventTypeLabel($event['event_type'] ?? 'followup')) ?></em></article><?php endforeach; ?><?php if (empty($followups)): ?><div class="proma-empty-state"><p>پیگیری زمان‌بندی‌شده‌ای ثبت نشده است.</p></div><?php endif; ?></div></section></div>
